<script setup lang="ts">
import {computed,ref} from 'vue';
import type {PublicView,Command} from '../core/types';
import type {Locale} from '../ui/i18n';
import {alpha2Text} from './i18n';
const props=defineProps<{view:PublicView;locale:Locale;disabled:boolean}>();
const emit=defineEmits<{command:[Command]}>();
const t=(key:string)=>alpha2Text(props.locale,key),selected=ref(0);
const near=computed(()=>props.view.alpha2!.facilities.filter(f=>f.near));
const item=computed(()=>props.view.alpha2!.bag.find(i=>i.id===selected.value));
</script>
<template><section class="card feature-map"><h2>{{t('minimap')}}</h2><svg viewBox="0 0 340 126" role="img" :aria-label="t('minimap')"><template v-for="(row,floor) in view.explored" :key="floor"><text x="1" :y="floor*20+13">{{floor+1}}</text><rect v-for="x in row" :key="x" :x="14+x*10" :y="floor*20+5" width="9" height="8" fill="#829a98"/></template><line v-for="l in view.map.ladders" :key="`${l.floor}:${l.x}`" :x1="18+l.x*10" :x2="18+l.x*10" :y1="l.floor*20+8" :y2="(l.floor+1)*20+8" stroke="#e6c788"/><rect v-for="d in view.alpha!.doors" :key="d.id" :x="16+d.x*10" :y="d.floor*20+3" width="4" height="12" :fill="d.open?'#76af94':'#d68b61'"/><circle :cx="18+view.player.x*10" :cy="view.player.floor*20+8" r="4" fill="#fff1bc"/></svg><p>{{t('mapLegend')}}</p><div class="segment-tags"><span v-for="segment in view.alpha2!.segments.filter(s=>s.floor===view.player.floor)" :key="segment.id">{{t(segment.tag)}} · {{segment.start}}–{{segment.end}}</span></div></section>
<section class="card facilities"><h2>{{t('facilities')}}</h2><p v-if="!near.length">{{t('noNearFeature')}}</p><div v-for="door in view.alpha!.doors.filter(d=>d.floor===view.player.floor&&Math.abs(d.x-view.player.x)<=1)" :key="`d${door.id}`" class="feature"><button :data-lever="door.id" v-if="door.locked" :disabled="disabled" @click="emit('command',`lever:${door.id}`)">{{t('gateCrank')}}</button><button :data-door="door.id" v-else :disabled="disabled" @click="emit('command',`door:${door.id}`)">{{t(door.open?'closeDoor':'openDoor')}}</button></div>
<label v-if="near.some(f=>['merchant','altar','campfire'].includes(f.kind))" class="trade-select">{{t('tradeTarget')}}<select v-model.number="selected" :aria-label="t('tradeTarget')"><option :value="0">—</option><option v-for="i in view.alpha2!.bag" :key="i.id" :value="i.id">{{i.name[locale]}}</option></select></label>
<article v-for="f in near" :key="f.id" class="feature" :data-feature="f.kind"><b>{{f.name[locale]}}</b><p>{{f.description[locale]}}</p><small v-if="f.used">{{t('usedFeature')}}</small><template v-if="f.kind==='merchant'"><p>{{t('shopFunds')}} {{f.gold}}</p><div v-for="stock in f.stock" :key="stock.id" class="shop-item"><span>{{stock.name[locale]}}</span><button :disabled="disabled||view.player.gold<stock.buy!" :data-buy="stock.id" @click="emit('command',`a2:buy:${f.id}:${stock.id}`)">{{t('buy')}} · {{stock.buy}}</button></div><div class="item-actions" v-if="item"><button :disabled="disabled||!!item.equipped||(f.gold??0)<(item.sell??0)" @click="emit('command',`a2:sell:${f.id}:${item.id}`)">{{t('sell')}} · {{item.sell}}</button><button v-if="item.category==='wand'" :disabled="disabled||view.player.gold<8" @click="emit('command',`a2:recharge:${f.id}:${item.id}`)">{{t('recharge')}}</button></div></template>
<button v-if="f.kind==='altar'" :disabled="disabled||!item||view.player.gold<12" @click="item&&emit('command',`a2:cleanse:${f.id}:${item.id}`)">{{t('cleanse')}}</button><button v-if="f.kind==='campfire'" :disabled="disabled||item?.category!=='food'" @click="item&&emit('command',`a2:cook:${f.id}:${item.id}`)">{{t('cook')}}</button>
<template v-if="!f.used"><button v-if="f.kind==='fountain'" :disabled="disabled" @click="emit('command',`a2:feature:${f.id}:drink`)">{{t('featureDrink')}}</button><template v-if="f.kind==='chest'"><button :disabled="disabled||view.player.gold<10" @click="emit('command',`a2:feature:${f.id}:pay`)">{{t('pay')}}</button><button :disabled="disabled||view.player.hp<=7" @click="emit('command',`a2:feature:${f.id}:force`)">{{t('force')}}</button></template><button v-if="f.kind==='garden'" :disabled="disabled" @click="emit('command',`a2:feature:${f.id}:harvest`)">{{t('harvest')}}</button><button v-if="f.kind==='trap'" :disabled="disabled" @click="emit('command',`a2:feature:${f.id}:disarm`)">{{t('disarm')}}</button></template></article></section></template>
